//! Every case of `response_reason.jsonl` (not gated) against
//! `response_reason` and `response_trust`, with the sweep of
//! `check_reason` regenerated by the generator's rule and compared by
//! count and digest (`tests/contract/gen_response_reason.py`).

mod common;

use std::cell::RefCell;

use bettermemory_core::pyvalue::PyValue;
use bettermemory_core::response_reason::{
    check_reason, claim_at_index, row_reason, verdict_and_reason, with_objection, CheckReason,
    Raised,
};
use bettermemory_core::response_trust::{
    apply_trust, apply_trust_unavailable, attach_provenance, AttachError, Row, TrustRows,
    TRUST_UNAVAILABLE_RECOMMENDATION,
};
use bettermemory_core::store::provenance::TrustRow;
use bettermemory_core::unicode;
use common::parity::Ledger;
use serde_json::{json, Value};
use sha2::{Digest, Sha256};

const FILE: &str = "response_reason.jsonl";

/// A JSON value read as Python's `json.loads` reads it.
pub fn py(v: &Value) -> PyValue {
    match v {
        Value::Null => PyValue::None,
        Value::Bool(b) => PyValue::Bool(*b),
        Value::Number(n) if n.is_f64() => PyValue::Float(n.as_f64().unwrap()),
        Value::Number(n) => PyValue::int_from_decimal(&n.to_string()).unwrap(),
        Value::String(s) => PyValue::str(s),
        Value::Array(a) => PyValue::List(a.iter().map(py).collect()),
        Value::Object(m) => {
            PyValue::Dict(m.iter().map(|(k, v)| (PyValue::str(k), py(v))).collect())
        }
    }
}

fn js(v: &PyValue) -> Value {
    match v {
        PyValue::None => Value::Null,
        PyValue::Bool(b) => json!(b),
        PyValue::Int(t) => serde_json::from_str(t).unwrap(),
        PyValue::Float(f) => json!(f),
        PyValue::Str(s) => json!(unicode::to_string(s).unwrap()),
        PyValue::List(a) | PyValue::Tuple(a) => Value::Array(a.iter().map(js).collect()),
        PyValue::Dict(d) => Value::Object(
            d.iter()
                .map(|(k, v)| {
                    let PyValue::Str(k) = k else { panic!("a key") };
                    (unicode::to_string(k).unwrap(), js(v))
                })
                .collect(),
        ),
        other => panic!("unexpected {other:?}"),
    }
}

fn row(v: &Value) -> Row {
    match &py(v) {
        PyValue::Dict(d) => d.clone(),
        other => panic!("a row, got {other:?}"),
    }
}

fn text(r: Result<Option<Vec<u32>>, Raised>) -> Value {
    match r {
        Ok(None) => Value::Null,
        Ok(Some(t)) => json!(unicode::to_string(&t).unwrap()),
        Err(e) => json!({ "raised": format!("{e:?}") }),
    }
}

/// `check_reason`'s arguments from the case's keywords.
pub fn args(a: &Value) -> CheckReason {
    let mut c = CheckReason::default();
    let m = a.as_object().unwrap();
    for (k, v) in m {
        let p = py(v);
        match k.as_str() {
            "missing" => c.missing = p,
            "anchored_missing" => c.anchored_missing = p,
            "attested_absent_present" => c.attested_absent_present = p,
            "commits" => c.commits = p,
            "claims_drifted" => c.claims_drifted = p,
            "leg_note" => c.leg_note = p,
            "remote" => c.remote = v.as_bool().unwrap(),
            "trust_unavailable" => c.trust_unavailable = v.as_bool().unwrap(),
            "untrusted" => c.untrusted = v.as_str().map(str::to_owned),
            "contradicted_by" => c.contradicted_by = p,
            "rejections" => c.rejections = p,
            other => panic!("unknown keyword {other}"),
        }
    }
    c
}

struct Stub {
    st: Value,
    asked: RefCell<Option<Vec<String>>>,
}

impl TrustRows for Stub {
    type Error = ();
    fn trust_rows(&self, ids: &[String]) -> Result<Option<Vec<(String, TrustRow)>>, ()> {
        *self.asked.borrow_mut() = Some(ids.to_vec());
        match &self.st {
            Value::Null => Ok(None),
            Value::String(_) => Err(()),
            Value::Object(m) => Ok(Some(
                m.iter()
                    .map(|(k, v)| {
                        let trust = TrustRow {
                            label: v[0].as_str().unwrap().to_owned(),
                            verified_at: v[1].as_str().map(str::to_owned),
                        };
                        (k.clone(), trust)
                    })
                    .collect(),
            )),
            other => panic!("a store {other}"),
        }
    }
    fn verifies(&self) -> bool {
        !self.st.is_null()
    }
}

fn answer(case: &Value) -> Value {
    let a = &case["a"];
    match case["f"].as_str().unwrap() {
        "cr" => text(check_reason(&args(a))),
        "vr" => match verdict_and_reason(&row(a)) {
            Ok((v, r)) => json!([js(&v), text(Ok(r))]),
            Err(e) => json!({ "raised": format!("{e:?}") }),
        },
        "rr" => text(row_reason(&row(&a["row"]), &py(&a["c"]), a["u"].as_str())),
        "wo" => js(&with_objection(&py(&a[0]), a[1].as_bool().unwrap())),
        "ci" => text(claim_at_index(&row(&a[0]), a[1].as_i64().unwrap())),
        "tu" => {
            let mut r = row(&a["row"]);
            let rec = a.get("rec").and_then(Value::as_str);
            apply_trust_unavailable(&mut r, rec.unwrap_or(TRUST_UNAVAILABLE_RECOMMENDATION));
            js(&PyValue::Dict(r))
        }
        "at" => {
            let mut r = row(&a["row"]);
            apply_trust(
                &mut r,
                a["p"].as_str(),
                a["v"].as_str(),
                a["s"].as_i64().unwrap(),
            );
            js(&PyValue::Dict(r))
        }
        "ap" => {
            let mut rows: Vec<Row> = a["rows"].as_array().unwrap().iter().map(row).collect();
            let stub = Stub {
                st: a["st"].clone(),
                asked: RefCell::new(None),
            };
            let got = attach_provenance(&mut rows, &stub, a["s"].as_i64().unwrap());
            let out: Vec<Value> = rows.into_iter().map(|r| js(&PyValue::Dict(r))).collect();
            let mut o = json!({ "q": stub.asked.into_inner(), "out": out });
            match got {
                Ok(()) => {}
                Err(AttachError::Store(())) => o["raised"] = json!("RuntimeError"),
                Err(AttachError::Unhashable) => o["raised"] = json!("TypeError"),
                Err(AttachError::Encode) => o["raised"] = json!("UnicodeEncodeError"),
            }
            o
        }
        other => panic!("unknown function {other}"),
    }
}

/// The generator's `_sweep`, in its order.
pub fn sweep() -> Vec<CheckReason> {
    let p = ["a.py", "b/c.md", "d", "e.txt", "f"];
    let strs = |xs: &[&str]| PyValue::List(xs.iter().map(|s| PyValue::str(s)).collect());
    let rej = |n: usize| {
        let one = json!({"count_in_window": 1, "most_recent_ts": "2026-01-02T03:04:05Z", "outcome": "ignored"});
        let two = json!({"count_in_window": 4, "most_recent_ts": "2026-02-03T00:00:00+00:00", "outcome": "contradicted"});
        PyValue::List([one, two][..n].iter().map(py).collect())
    };
    let anchored: [&[&str]; 4] = [&[], &["b/c.md"], &["x", "a.py"], &p];
    let commits = [
        PyValue::None,
        PyValue::int(0),
        PyValue::int(1),
        PyValue::int(2),
        PyValue::Bool(true),
    ];
    let mut out = Vec::new();
    for m in [0, 1, 3, 4, 5] {
        for an in anchored {
            for at in [0, 1, 4] {
                for c in &commits {
                    for cl in [0, 1, 4] {
                        for ln in [None, Some("Leg.")] {
                            for rm in [false, true] {
                                for tu in [false, true] {
                                    for ut in [None, Some("Untrusted.")] {
                                        for cb in [0, 1, 4] {
                                            for rj in [0, 1, 2] {
                                                out.push(CheckReason {
                                                    missing: strs(&p[..m]),
                                                    anchored_missing: strs(an),
                                                    attested_absent_present: strs(&p[..at]),
                                                    commits: c.clone(),
                                                    claims_drifted: strs(&p[..cl]),
                                                    leg_note: ln
                                                        .map_or(PyValue::None, PyValue::str),
                                                    remote: rm,
                                                    trust_unavailable: tu,
                                                    untrusted: ut.map(str::to_owned),
                                                    contradicted_by: strs(&p[..cb]),
                                                    rejections: rej(rj),
                                                });
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    out
}

#[test]
fn response_reason_every_case() {
    let lines = common::jsonl(FILE);
    let header = &lines[0];
    let cases = &lines[1..];
    assert_eq!(header["count"].as_u64().unwrap() as usize, cases.len());
    let mut ledger = Ledger::new("golden_response_reason", FILE);
    for (i, case) in cases.iter().enumerate() {
        if case["f"] == "sweep" {
            ledger.case(format!("#{i} sweep"), || {
                let all = sweep();
                let mut h = Sha256::new();
                for a in &all {
                    match check_reason(a).expect("the sweep raises nothing") {
                        None => h.update(b"\0"),
                        Some(t) => h.update(unicode::to_string(&t).unwrap().as_bytes()),
                    }
                    h.update(b"\n");
                }
                let hex: String = h.finalize().iter().map(|b| format!("{b:02x}")).collect();
                assert_eq!(all.len() as u64, case["n"].as_u64().unwrap(), "sweep count");
                assert_eq!(hex, case["sha256"].as_str().unwrap(), "sweep digest");
            });
            continue;
        }
        ledger.case(format!("#{i} {}", case["a"]), || {
            assert_eq!(answer(case), case["o"], "case #{i} {}", case["a"]);
        });
    }
    ledger.finish(cases.len());
}
